{"path": "csvline.py", "content": "def parse_line(line):
    """Split one CSV line (RFC 4180): fields separated by commas; a field may be quoted with
    double quotes, and inside quotes commas are literal and a doubled quote ("") is one quote.
    Returns the list of field strings."""
    fields = []
    field = []
    in_quotes = False
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if in_quotes:
            if c == '"':
                if i + 1 < n and line[i + 1] == '"':
                    field.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                field.append(c)
        elif c == '"':
            in_quotes = True
        elif c == ',':
            fields.append(''.join(field))
            field = []
        else:
            field.append(c)
        i += 1
    fields.append(''.join(field))
    return fields
